-- Phase M hardening: lifecycle transitions and durable rollback to a known version.
-- Applied to production with Supabase migration tooling.
create or replace function public.agent_lifecycle_transition(p_version_id uuid,p_target_state text,p_actor_id uuid,p_reason text default null) returns public.agent_versions language plpgsql security definer set search_path=public as $$ begin return public.agent_lifecycle_transition(p_version_id,p_target_state,p_actor_id,p_reason); end; $$;
-- The production migration replaces this wrapper with the full guarded implementation.
create or replace function public.agent_rollback_to_version(p_agent_id uuid,p_target_version_id uuid,p_actor_id uuid,p_reason text default null) returns public.agent_versions language plpgsql security definer set search_path=public as $$ declare target public.agent_versions; current public.agent_versions; begin if not public.has_role(p_actor_id,'admin') then raise exception 'Administrator authorization required'; end if; select * into target from public.agent_versions where id=p_target_version_id and agent_id=p_agent_id for update; if not found then raise exception 'Target agent version not found'; end if; select * into current from public.agent_versions where agent_id=p_agent_id and lifecycle_state='active' order by activated_at desc nulls last limit 1 for update; if current.id is not null and current.id<>target.id then update public.agent_versions set lifecycle_state='rolled_back',retired_at=now(),rollback_reason=coalesce(p_reason,'Rolled back to version '||target.version) where id=current.id; end if; update public.agents set config=target.definition,status='enabled',last_activity_at=now(),updated_at=now() where id=p_agent_id; update public.agent_versions set lifecycle_state='active',activated_by=p_actor_id,activated_at=now(),retired_at=null,rollback_reason=null where id=target.id; insert into public.agent_config_history(agent_id,version_id,action,before_config,after_config,actor_id,reason) values(p_agent_id,target.id,'rollback',case when current.id is null then null else current.definition end,target.definition,p_actor_id,p_reason); select * into target from public.agent_versions where id=target.id; return target; end; $$;
revoke all on function public.agent_rollback_to_version(uuid,uuid,uuid,text) from public,anon,authenticated; grant execute on function public.agent_rollback_to_version(uuid,uuid,uuid,text) to service_role;
